def prefixRepetitions(s):
    n = len(s)
    pi = [0] * n
    k = 0
    for i in range(1, n):
        while k and s[i] != s[k]:
            k = pi[k - 1]
        if s[i] == s[k]:
            k += 1
        pi[i] = k
    res = []
    for i in range(n):
        L = i + 1
        per = L - pi[i]
        res.append(L // per if L % per == 0 else 1)
    return res
